const PR_IN_SUBJECT = /\(#(\d+)\)$/; // "[FE] RH-6589: ... (#2445)"
const SKIP = /(^|\/)(tests?|e2e)\/|(^|\/)(package-lock\.json|uv\.lock)$|_pb2(_grpc)?\.py$/;
const HUNK = /^@@ -(\d+)(?:,(\d+))? /;

export function introducingPrs(fcp: string, fixSha: string): Map<number, number> {
  const blamedLines = new Map<number, number>(); // PR number -> lines it wrote that the fix changed
  let path = "";
  for (const line of git(fcp, "diff", "-U0", `${fixSha}^`, fixSha).split("\n")) {
    if (line.startsWith("--- a/")) path = line.slice(6);
    const hunk = HUNK.exec(line);
    const count = Number(hunk?.[2] ?? 1);
    if (hunk === null || count === 0 || SKIP.test(path)) continue;
    const from = Number(hunk[1]);
    const porcelain = git(fcp, "blame", "-w", "-M", "-C", "--porcelain", `-L${from},${from + count - 1}`, `${fixSha}^`, "--", path);
    for (const sha of porcelain.match(/^[0-9a-f]{40}(?= \d+ \d+)/gm) ?? []) {
      const pr = Number(PR_IN_SUBJECT.exec(git(fcp, "log", "-1", "--format=%s", sha).trim())?.[1]);
      if (pr > 0) blamedLines.set(pr, (blamedLines.get(pr) ?? 0) + 1);
    }
  }
  return blamedLines;
}

