const HUNK = /^@@ -(\d+)(?:,(\d+))? /;

const git = (...args: string[]): string => execFileSync("git", args, { encoding: "utf8" });

export const introducingPrs = (fixSha: string): Map<number, number> => {
  const blamed = new Map<number, number>();
  let path = "";
  for (const line of git("diff", "-U0", `${fixSha}^`, fixSha).split("\n")) {
    if (line.startsWith("--- a/")) path = line.slice(6);
    const hunk = HUNK.exec(line);
    const count = Number(hunk?.[2] ?? 1);
    if (hunk === null || count === 0 || SKIP.test(path)) continue;
    const from = Number(hunk[1]);
    const porcelain = git("blame", "-w", "-M", "-C", "--porcelain", `-L${from},${from + count - 1}`, `${fixSha}^`, "--", path);
    for (const sha of porcelain.match(/^[0-9a-f]{40}(?= \d+ \d+)/gm) ?? []) {
      const pr = Number(PR_IN_SUBJECT.exec(git("log", "-1", "--format=%s", sha).trim())?.[1]);
      if (pr > 0) blamed.set(pr, (blamed.get(pr) ?? 0) + 1);
    }
  }
  return blamed;
};

